function renderSectionNavNew() { const links: Array<[string, string]> = [['scenario', '01 Scenario'], ['land-requirement', '02 Land requirement'], ['establishment', '03 Establishment timeline'], ['food', '04 Food requirement'], ['food-labour', 'Food-production labour'], ['agroecosystem', 'Agroecosystem planner'], ['food-protein', 'Food & protein'], ['heating', '05 Heating'], ['annual-crops', '06 Annual crops'], ['perennial-crops', '07 Perennial crops'], ['method', '08 Method & sources']]; return `<nav class="section-nav" aria-label="Land and carrying-capacity sections"><span>On this page</span>${links.map(([id, label]) => `<a href="#${id}">${label}</a>`).join('')}</nav>`; }
function renderScenarioSummaryNew(result: any) { const site = state.contract.site_classes[state.site]; const local = site.local_environment ?? {}; const buildingCount = state.buildings.length; const totalFloor = state.buildings.reduce((sum: number, building: Building) => sum + Number(building.floor_area_m2 || 0), 0); return `<div class="scenario-summary"><div class="metric"><span>Household</span><strong>${state.members.length} ${state.members.length === 1 ? 'person' : 'people'}</strong><small>${esc(state.members.map((member) => member.label).join(' · '))}</small></div><div class="metric"><span>Site condition</span><strong>${esc(site.label)}</strong><small>${esc(local.cli_capability_class_band ?? 'Scenario capability band')}</small></div><div class="metric"><span>Heated buildings</span><strong>${buildingCount} · ${fmt(totalFloor, 1)} m²</strong><small>${esc(state.buildings.map((building) => building.label).join(' · '))}</small></div><div class="metric"><span>Local context</span><strong>${fmt(state.contract.environment.climate.growing_degree_days.value_degree_days, 0)} °C·day</strong><small>${fmt(state.contract.environment.climate.frost_free_period.average_length_days, 0)} frost-free days · ${fmt(state.contract.environment.climate.heating_degree_days.value_degree_days, 0)} heating degree days</small></div></div>`; }
function renderScenarioSectionNew(result: any) { const siteOptions: Array<[string, string]> = [['wetter_productive', 'Favourable / productive'], ['ordinary_mesic', 'Ordinary / mesic'], ['dry', 'Dry / moisture-limited'], ['shallow_rocky_marginal', 'Marginal / shallow / rocky']]; const presetOptions: Array<[string, string]> = [['reference_adult_man', 'Reference adult man · editable starting case'], ...state.contract.household_presets.map((row: any) => [row.id, row.label]), ['custom', 'Custom household']]; return `<section class="section" id="scenario"><div class="section-heading"><p class="eyebrow">01 · scenario</p><h2>Choose the household and place</h2><p>Set the people, site condition and heated building load. The result below updates immediately from this scenario.</p></div>${renderScenarioSummaryNew(result)}<div class="controls-row scenario-controls">${selectControl('preset', 'Household', presetOptions, state.preset)}${selectControl('site', 'Site condition', siteOptions, state.site)}</div><p class="small-note">Site bands are transparent scenario capability ranges informed by Owen Sound / Grey County climate and the Ontario soil-capability framework; they are not parcel-level soil classifications.</p></section>`; }
function landComparisonTextNew(establishment: number, mature: number, allocation: number, peakYear: unknown) { const difference = allocation - establishment; const comparison = difference >= 0 ? `leaving the proposed ${area(allocation)} allocation ${area(difference)} above the establishment peak` : `leaving the proposed ${area(allocation)} allocation ${area(Math.abs(difference))} short during establishment`; return `On the selected ${state.contract.site_classes[state.site].label.toLowerCase()} site, this household peaks at ${area(establishment)} in ${peakYear === 'mature' ? 'the mature state' : `Year ${peakYear}`} and settles to ${area(mature)} at maturity, ${comparison}.`; }
function renderDemandScopeNew(result: any) { const profile = result.custom.food_demand_profile ?? {}; const accounting = result.custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const dependentSupplement = peak?.dependent_food_supplement_annual_area_ha ?? 0; return `<div class="demand-scope"><div class="metric"><span>Current household demand</span><strong>${energy(profile.current_household_food_demand_gj_year ?? result.demand)}</strong><small>Adults + currently dependent children</small></div><div class="metric"><span>Permanent adult demand</span><strong>${energy(profile.permanent_adult_food_demand_gj_year ?? result.custom.permanent_adult_food_demand_gj_year)}</strong><small>Sizes the permanent perennial footprint</small></div><div class="metric"><span>Dependent food demand</span><strong>${energy(profile.dependent_child_food_demand_gj_year ?? result.custom.dependent_child_food_demand_gj_year)}</strong><small>Pooled while children remain dependent</small></div><div class="metric"><span>Permanent perennial footprint</span><strong>${area(accounting?.planted_perennial_footprint_ha ?? 0)}</strong><small>Dependent supplement at peak: ${area(dependentSupplement)}</small></div><p class="small-note">Children add to pooled household food demand while dependent, but do not add a permanent perennial allocation to the parental parcel. Annual and perennial food can feed everyone; after adulthood, their long-term allocation is outside this calculation.</p></div>`; }
function renderLandRequirementLegacy(result: any) { const custom = result.custom; const accounting = custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const establishment = accounting?.establishment_land_requirement_ha ?? custom.robust_minimum_area_ha; const mature = accounting?.mature_land_requirement_ha ?? custom.robust_minimum_area_ha; const allocation = custom.arc_policy_allocation_ha ?? 0; const difference = allocation - establishment; const parts = peak ? [{id: 'annual', label: 'Annual bridge at peak', area_ha: peak.annual_area_ha}, {id: 'perennial', label: 'Planted perennial footprint', area_ha: peak.planted_perennial_footprint_ha}, {id: 'wood', label: 'Renewable heating biomass', area_ha: peak.heating_area_ha}, {id: 'reserve', label: 'Exclusive resilience reserve', area_ha: peak.exclusive_resilience_reserve_ha}] : custom.land_allocation.parts; return `${renderDemandScopeNew(result)}<div class="land-result"><div class="land-headline-grid"><div class="metric land-primary"><span>Land needed to establish</span><strong>${area(establishment)}</strong><small>Peak requirement from bare land</small></div>${metric('Mature land requirement', area(mature), 'After perennial establishment')}${metric('ARC allocation', area(allocation), 'Policy comparison')}${metric('Establishment surplus / deficit', difference >= 0 ? `+${area(difference)}` : `−${area(Math.abs(difference))}`, difference >= 0 ? 'surplus' : 'deficit')}${metric('Peak year', peak?.year === 'mature' ? 'Mature' : `Year ${peak?.year ?? '—'}`, 'Highest exclusive footprint')}</div><p class="land-interpretation">${esc(landComparisonTextNew(establishment, mature, allocation, peak?.year))}</p><div class="land-breakdown"><div><h3>Peak establishment footprint</h3><div class="allocation"><div class="allocation-bar">${parts.map((part: any) => `<span class="${part.id}" style="width:${Math.max(2, Number(part.area_ha) / Math.max(establishment, .01) * 100)}%" title="${esc(part.label)} ${area(part.area_ha)}"></span>`).join('')}</div><div class="allocation-legend">${parts.map((part: any) => `<span><i class="swatch ${part.id}"></i>${esc(part.label)} <b>${area(part.area_ha)}</b></span>`).join('')}${peak ? `<span><i class="swatch overlap"></i>Valid intercropping overlap <b>−${area(peak.young_forest_annual_intercrop_overlap_ha)}</b></span>` : ''}</div></div></div>${renderLandSvg(result)}</div><div class="housing-note"><h3>Housing density ≠ biological carrying capacity</h3><p>Compact housing can reduce building footprint, roads, utilities and transport distances. Residents still require food, materials and energy. When those flows are imported, the productive land and energy flows occur elsewhere.</p><blockquote>You can concentrate houses. You cannot eliminate the land and energy flows that sustain the people inside them.</blockquote></div></div>`; }
function renderLandRequirementNew(result: any) { const custom = result.custom; const accounting = custom.establishment_land?.strategy_comparison?.progressive_handoff; const peak = accounting?.rows?.find((row: any) => row.year === accounting.establishment_peak_year) ?? accounting?.rows?.[0]; const establishment = accounting?.establishment_land_requirement_ha ?? custom.robust_minimum_area_ha; const mature = accounting?.mature_land_requirement_ha ?? custom.robust_minimum_area_ha; const allocation = custom.arc_policy_allocation_ha ?? 0; const difference = allocation - establishment; return `${renderDemandScopeNew(result)}<div class="land-result"><div class="land-headline-grid"><div class="metric land-primary"><span>Land needed to establish</span><strong>${area(establishment)}</strong><small>Peak requirement from bare land</small></div>${metric('Mature land requirement', area(mature), 'After perennial establishment')}${metric('ARC allocation', area(allocation), 'Policy comparison')}${metric('Establishment surplus / deficit', difference >= 0 ? `+${area(difference)}` : `−${area(Math.abs(difference))}`, difference >= 0 ? 'surplus' : 'deficit')}${metric('Peak year', peak?.year === 'mature' ? 'Mature' : `Year ${peak?.year ?? '—'}`, 'Highest exclusive footprint')}</div><p class="land-interpretation">${esc(landComparisonTextNew(establishment, mature, allocation, peak?.year))}</p>${renderLandSvg(result)}<div class="housing-note"><h3>Housing density ≠ biological carrying capacity</h3><p>Compact housing can reduce building footprint, roads, utilities and transport distances. Residents still require food, materials and energy. When those flows are imported, the productive land and energy flows occur elsewhere.</p><blockquote>You can concentrate houses. You cannot eliminate the land and energy flows that sustain the people inside them.</blockquote></div></div>`; }
function renderEstablishmentSectionNew(result: any) { const accounting = result.custom.establishment_land?.strategy_comparison?.progressive_handoff; return `<section class="section tinted" id="establishment"><div class="section-heading"><p class="eyebrow">03 · establishment timeline</p><h2>Why the establishment peak is different</h2><p>Perennial land is planted from Year 1, even before it produces much food. Annual bridge acreage then contracts as berries, nuts and fruit systems mature.</p></div><div class="timeline-peak"><strong>Peak year</strong><span>${accounting?.establishment_peak_year === 'mature' ? 'Mature' : `Year ${accounting?.establishment_peak_year ?? '—'}`}</span><small>${area(accounting?.establishment_land_requirement_ha ?? 0)} total exclusive footprint</small></div>${renderTimeline(result)}</section>`; }
function renderFoodProductionLabourSection(result: any) {
  const ledger = result.custom.food_production_labour ?? {};
  const stages = ledger.stages ?? [];
  if (!stages.length) return '';
  const labels: Record<string, string> = {annual_crops: 'Annual crops', perennial_food_forest: 'Perennial food forest', livestock: 'Livestock', harvesting: 'Harvesting', food_preservation_storage: 'Preservation / storage', fertility_nutrient_cycling: 'Fertility / nutrient cycling', seed_propagation: 'Seed / propagation', water_management: 'Water management', system_maintenance: 'System maintenance'};
  const stageLabel = (year: any) => year === 0 ? 'Year 0 · establishment' : year === 'mature' ? 'Mature' : `Year ${year}`;
  const nutritionLabel = (row: any) => row.nutrition?.status === 'not_yet_producing' ? 'Not yet producing' : row.nutrition?.energy?.adequate === false ? 'Food-energy deficit' : row.nutrition?.protein?.adequate === false ? 'Protein constraint' : 'Nutrition screen reported';
  const peak = ledger.stages.find((row: any) => row.year === ledger.peak_stage) ?? ledger.stages[0];
  const recurringPeak = ledger.stages.reduce((best: any, row: any) => Number(row.recurring_hours_year ?? 0) > Number(best?.recurring_hours_year ?? -1) ? row : best, ledger.stages[0]);
  const capacityRows = result.custom.food_labour_capacity ?? [];
  const peakCapacity = capacityRows.find((row: any) => row.year === peak?.year) ?? capacityRows[0];
  const missing = ledger.missing_data ?? [];
  const auditTable = (row: any) => `<details class="method labour-audit"><summary>Show task and production audit for ${esc(stageLabel(row.year))}</summary><p><strong>Fixed demand:</strong> ${energy(row.household_food_demand_gj_year)} · ${fmt(row.people_fed, 0)} person fed · ${fmt(row.annual_area_ha, 3)} ha annual + ${fmt(row.perennial_area_ha, 3)} ha perennial.</p><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Crop/species</th><th>Task</th><th>Coefficient</th><th>Unit</th><th>Harvest kg</th><th>Bearing</th><th>Hours</th><th>Source</th></tr></thead><tbody>${(row.audit_rows ?? []).map((task: any) => `<tr><th scope="row">${esc(task.crop_or_species ?? task.production_id)}</th><td>${esc(task.labour_task)}</td><td>${fmt(task.coefficient, 1)}</td><td>${esc(task.coefficient_unit ?? '')}</td><td>${task.edible_harvest_kg_year == null ? '—' : fmt(task.edible_harvest_kg_year, 1)}</td><td>${task.bearing_factor == null ? '—' : fmt(task.bearing_factor, 2)}</td><td><strong>${fmt(task.calculated_hours, 1)}</strong></td><td>${task.source ? sourceLinks(task.source) : 'Planning row'}</td></tr>`).join('')}</tbody></table></div><p class="small-note">Visible task rows: ${fmt(row.task_hours_reconciliation?.visible_task_rows_hours, 1)} h; reported total: ${fmt(row.task_hours_reconciliation?.reported_total_hours, 1)} h; difference: ${fmt(row.task_hours_reconciliation?.difference_hours, 3)} h. No task normalization is applied.</p></details>`;
  const externalSummary = (row: any) => `<details class="method"><summary>External-input and closed-loop ledger</summary><p><strong>Status:</strong> ${esc(row.closed_loop_status ?? 'unresolved')} · the food ledger is not called closed-loop while nutrient return, propagation, water, equipment energy or mineral replacement remains unquantified.</p><p><strong>Establishment external inputs:</strong> ${(row.external_input_ledger?.establishment_external_inputs ?? []).map((item: any) => esc(item.id)).join(', ') || 'none listed'}</p><p><strong>Recurring external inputs:</strong> ${(row.external_input_ledger?.recurring_external_inputs ?? []).map((item: any) => esc(item.id)).join(', ') || 'none quantified'}</p><p><strong>Internally regenerated or shared flows:</strong> ${(row.external_input_ledger?.internally_regenerated_inputs ?? []).map((item: any) => esc(item.id)).join(', ') || 'none quantified'}</p><p><strong>Unresolved dependencies:</strong> ${(row.unresolved_work ?? []).map((item: any) => esc(item.id)).join(', ') || 'none'}</p><p class="small-note">The attached nutrient ledger reports only currently wired crop-export, residue, fixation and humanure flows. Missing streams are unresolved, not zero.</p></details>`;
  return `<section class="section" id="food-labour"><div class="section-heading"><p class="eyebrow">Food-production labour</p><h2>Human time through establishment</h2><p>This comparison holds the selected reference adult's food demand constant. Only the food-production system changes as annual crops bridge the establishment years and perennial layers mature.</p></div><div class="metric-grid four">${metric('Peak total labour', `${fmt(ledger.peak_hours_year, 0)} h/year`, `${stageLabel(ledger.peak_stage)} · ${fmt(ledger.peak_hours_year / 52.18, 1)} h/week`)}${metric('Peak recurring labour', `${fmt((recurringPeak?.recurring_hours_year ?? 0), 0)} h/year`, `${stageLabel(recurringPeak?.year)} · harvest, care and processing`)}${metric('Projection', 'Fixed household', 'same person and food demand at every stage')}${metric('Closed-loop status', 'Unresolved', 'nutrient, propagation, water and equipment dependencies remain visible')}</div><div class="table-scroll"><table class="evidence-table labour-table"><caption>Fixed-demand production, nutrition and human effort by stage</caption><thead><tr><th>Stage</th><th>Annual area</th><th>Perennial area</th><th>Annual food</th><th>Perennial food</th><th>Establishment</th><th>Recurring</th><th>Total h/year</th><th>Avg h/week</th><th>Peak h/week</th><th>Nutrition</th></tr></thead><tbody>${stages.map((row: any) => `<tr><th scope="row">${esc(stageLabel(row.year))}</th><td>${fmt(row.annual_area_ha, 3)} ha</td><td>${fmt(row.perennial_area_ha, 3)} ha</td><td>${fmt(row.food?.annual_food_percent, 1)}%</td><td>${fmt(row.food?.perennial_food_percent, 1)}%</td><td>${fmt(row.establishment_hours_year, 0)} h</td><td>${fmt(row.recurring_hours_year, 0)} h</td><td><strong>${fmt(row.total_hours_year, 0)} h</strong></td><td>${fmt(row.average_hours_week, 1)}</td><td>${fmt(row.seasonal_peak_hours_week, 1)}</td><td>${esc(nutritionLabel(row))}</td></tr>`).join('')}</tbody></table></div><div class="labour-category-grid"><div><h3>Work categories at the recurring peak</h3><dl>${Object.entries(recurringPeak?.categories ?? {}).map(([id, value]) => `<div><dt>${esc(labels[id] ?? id)}</dt><dd>${fmt(value, 0)} h/year</dd></div>`).join('')}</dl></div><div><h3>Scope and assumptions</h3><p>Year 0 is <strong>food-crop and perennial establishment labour</strong>, not total site establishment. Fencing, water-system installation, access work, earthworks and other infrastructure are unresolved separately.</p><p>Task coefficients are additive planning estimates. Harvest and preservation respond to actual production quantities where the ledger supplies harvest mass. Perennial watering, weed suppression, pruning, protection and monitoring use separate development curves rather than a generic bearing multiplier.</p><p class="small-note">Mechanization: ${esc(ledger.mechanization_assumption?.label ?? 'low-input household-scale manual system')}. Machine operator time remains human labour; recurring fuel/electricity dependence is unresolved.</p></div></div><details class="method"><summary>Fixed-demand stage audit tables</summary>${stages.map(auditTable).join('')}</details>${externalSummary(peak)}${missing.length ? `<details class="method"><summary>Unresolved labour mappings</summary><ul>${missing.map((row: any) => `<li>${esc(row.id)}${row.year == null ? '' : ` · Year ${esc(row.year)}`}: ${esc(row.reason)}</li>`).join('')}</ul></details>` : ''}<details class="method"><summary>Labour capacity comparison</summary><p>Available food-production hours are separate from food consumption. This single-adult golden scenario does not infer labour from age, household size or food demand.</p>${peakCapacity ? `<p><strong>${esc(peakCapacity.status)}</strong> · required ${fmt(peakCapacity.required_hours_week, 1)} h/week · available ${fmt(peakCapacity.available_hours_week, 1)} h/week · utilization ${fmt(peakCapacity.utilization_percent, 0)}%</p>` : '<p>No available food-production labour capacity was supplied.</p>'}</details><a class="back-top" href="#top">Back to top</a></section>`;
}

function renderHouseCostPage() {
  const result = houseCostResult();
  const presentation = buildHouseCostPresentationContract({...houseCostOptions(), taxRate: undefined, contingencyRate: undefined});
  const geometry = result.geometry;
  const bands = presentation.bands;
  const sensitivity = presentation.diameter_sensitivity;
  const layouts = presentation.layout_comparison;
  const packageIds = new Set(['water_plumbing_sanitation', 'hot_water', 'household_electrical']);
  const rateRows = result.components.map((row: any) => {
    const packageDetails = packageIds.has(row.id) ? `<p><strong>Inclusive package:</strong> ${cad(row.package_total_cad)} total; ${cad(row.package_included_paid_labour_cad)} paid labour; ${cad(row.package_included_fee_cad)} included fee; ${cad(row.package_non_labour_cost_cad)} non-labour.</p><p>Changing the paid labour rate replaces the included labour allowance. It is not added on top.</p><p>${esc((row.package_scope ?? []).join('; '))}</p>` : '';
    const scopeDetails = (row.scope_ids ?? []).length ? `<p><strong>Scope:</strong> ${esc(row.scope_ids.join(', '))}. <strong>Excludes:</strong> ${esc((row.excludes_scope_ids ?? []).join(', ') || 'none recorded')}.</p>` : '';
    const feeDetails = row.package_fee_offset_cad ? `<p><strong>Included-fee offset:</strong> ${cad(row.package_fee_offset_cad)} is already inside the ARC utility package.</p>` : '';
    return `<tr><th scope="row">${esc(row.label)}</th><td>${fmt(row.quantity, 2)}</td><td>${esc(row.unit)}</td><td>${houseRateInput(row.id, row.base_unit_rate_cad, row.unit)}</td><td>${cad(row.material_cost_cad)}</td><td>${fmt(row.labour_hours_total, 1)} h</td><td>${cad(row.cash_cost_cad)}</td><td><details><summary>${esc(row.status)}</summary><p>${esc(row.source_note)}</p>${packageDetails}${scopeDetails}${feeDetails}</details></td></tr>`;
  }).join('');
  const thresholdRows = presentation.threshold_rules.map((rule: any) => `<tr><th scope="row">${esc(rule.label)}</th><td>${esc(rule.trigger)}</td><td>${result.thresholds.applied.some((row: any) => row.id === rule.id) ? '<span class="status selected">Applied</span>' : '<span class="status reference">Not applied</span>'}</td><td>${esc(rule.confidence)}</td><td>${esc(rule.source)}</td></tr>`).join('');
  const sourceRows = presentation.sources.map((source: any) => `<p><strong>${esc(source.institution)}: ${esc(source.title)}</strong><br><span>${esc(source.classification)}</span> · <a href="${esc(source.url)}" target="_blank" rel="noreferrer">source</a><br>${esc(source.note)}</p>`).join('');
  const layoutRows = layouts.map((row: any) => `<tr><th scope="row">${esc(row.label)}</th><td>${fmt(row.usable_floor_area_m2, 1)} m²</td><td>${cad(row.completed_dwelling_capital_cad)}</td><td>${cad(row.cost_per_usable_m2_cad)}/m²</td><td>${fmt(row.owner_labour_hours, 1)} h</td><td>${fmt(row.paid_labour_hours, 1)} h</td></tr>`).join('');
  const diameterRows = sensitivity.map((row: any) => `<tr><th scope="row">${esc(row.label)}</th><td>${fmt(row.usable_floor_area_m2, 1)} m²</td><td>${cad(row.completed_dwelling_capital_cad)}</td><td>${cad(row.cost_per_usable_m2_cad)}/m²</td><td>${row.thresholds.length ? row.thresholds.map((id: string) => esc(id)).join(', ') : 'None'}</td></tr>`).join('');
  const diameterBars = sensitivity.map((row: any) => `<div class="house-bar-row"><span>${esc(row.label)}</span><div class="house-bar-track"><i style="width:${Math.max(2, Number(row.completed_dwelling_capital_cad) / Math.max(...sensitivity.map((item: any) => Number(item.completed_dwelling_capital_cad)), 1) * 100)}%"></i></div><strong>${cad(row.completed_dwelling_capital_cad)}</strong></div>`).join('');
  const services = Object.entries(HOUSE_COST_EVIDENCE.servicing_modes).map(([id, mode]: [string, any]) => [id, mode.label] as [string, string]);
  const labourModes = Object.entries(HOUSE_COST_EVIDENCE.labour_modes).map(([id, mode]: [string, any]) => [id, mode.label] as [string, string]);
  const houseBandOptions: Array<[string, string]> = [['low', 'Low planning band'], ['central', 'Central planning band'], ['high', 'High planning band']];
  const layoutOptions: Array<[string, string]> = Object.entries(HOUSE_COST_EVIDENCE.layout_rules).map(([id, rule]: [string, any]) => [id, rule.label]);
  const ownershipOptions: Array<[string, string]> = [['financed', 'Financed dwelling'], ['owned_out_right', 'Owned outright']];
  const diameterPreset = HOUSE_COST_EVIDENCE.diameter_presets.some((row: any) => Math.abs(row.diameter_m - houseCostState.diameter_m) < .0001) ? String(houseCostState.diameter_m) : 'custom';
  const bridgeRows = result.legacy_reconciliation.bridge_rows.map((row: any) => `<tr><th scope="row">${esc(row.component)}</th><td>${esc(row.original_scope)}<br>${cad(row.original_amount_cad)}</td><td>${cad(row.former_model_amount_cad)}</td><td>${esc(row.new_scope)}<br>${cad(row.new_amount_cad)}</td><td>${cad(row.delta_from_former_model_cad)}</td></tr>`).join('');
  const bridge = result.legacy_reconciliation.bridge;
  const water = result.components.find((row: any) => row.id === 'water_plumbing_sanitation');
  const hotWater = result.components.find((row: any) => row.id === 'hot_water');
  const electrical = result.components.find((row: any) => row.id === 'household_electrical');
  return shell(`<section class="hero house-cost-hero" id="top"><div><p class="eyebrow">Resident-owned dwelling · planning calculator</p><h1>House Cost Calculator</h1><p class="lede">Explore yurt geometry, construction scope, utilities, owner labour and financing as a resident-owned four-season dwelling.</p><p class="small-note">Canadian dollars · metric units · planning estimates as of ${esc(HOUSE_COST_EVIDENCE.price_basis_date)}</p></div><div class="hero-callout"><span>Completed dwelling economic cost</span><strong>${cad(result.totals.economic_cost_cad)}</strong><small>${fmt(geometry.usable_floor_area_m2, 1)} m² usable · ${esc(result.labour.label)}</small></div></section><nav class="section-nav house-cost-nav" aria-label="House cost calculator sections"><span>On this page</span><a href="#answer">01 Answer</a><a href="#design">02 Design</a><a href="#cost-stack">03 Cost stack</a><a href="#sensitivity">04 Sensitivity</a><a href="#evidence">05 Evidence</a></nav><section class="section house-answer" id="answer"><div class="section-heading"><p class="eyebrow">At a glance</p><h2>What does this dwelling cost?</h2><p>The selected design is a resident-owned home. Land purchase, site lease, shared infrastructure and household operating costs are outside this calculation.</p></div><div class="metric-grid four">${metric('Usable floor area', `${fmt(geometry.usable_floor_area_m2, 1)} m²`, `${fmt(geometry.gross_floor_area_m2, 1)} m² gross after ${fmt(geometry.area_deductions_m2.total, 1)} m² deductions`)}${metric('Construction cash budget', cad(result.totals.upfront_cash_required_cad), 'cash expenditure, tax and contingency')}${metric('Economic cost', cad(result.totals.economic_cost_cad), 'cash budget plus owner-labour value')}${metric('Dwelling financing', `${cad(result.financing.monthly_debt_service_cad)}/month`, `${fmt(result.financing.amortization_years, 0)}-year amortization`)}</div><div class="house-answer-stack"><div><h3>Selected accounting stack</h3><dl class="house-cost-list"><div><dt>Shell</dt><dd>${cad(result.stages.shell.cash_cost_cad)}</dd></div><div><dt>Insulated / heated structure</dt><dd>${cad(result.stages.insulated_heated_structure.cash_cost_cad)}</dd></div><div><dt>Cash before tax and contingency</dt><dd>${cad(result.stages.completed_before_tax_and_contingency.cash_cost_cad)}</dd></div><div><dt>Tax / HST allowance</dt><dd>${cad(result.totals.taxes_cad)}</dd></div><div><dt>Contingency</dt><dd>${cad(result.totals.contingency_cad)}</dd></div><div><dt>Total cash construction budget</dt><dd>${cad(result.totals.upfront_cash_required_cad)}</dd></div><div><dt>Initial financing contribution</dt><dd>${cad(result.totals.initial_cash_contribution_cad)}</dd></div><div><dt>Financed principal</dt><dd>${cad(result.totals.financed_principal_cad)}</dd></div><div><dt>Owner labour economic value</dt><dd>${cad(result.totals.owner_labour_imputed_cad)}</dd></div><div class="total"><dt>Completed dwelling economic cost</dt><dd>${cad(result.totals.economic_cost_cad)}</dd></div></dl></div><div class="house-highlight"><p class="eyebrow">Historical ARC reference</p><strong>${cad(presentation.legacy_arc_benchmark.range_cad.low)} - ${cad(presentation.legacy_arc_benchmark.range_cad.high)}</strong><p>The historical exact integrated total is ${cad(result.legacy_reconciliation.legacy_exact_integrated_total_cad)}, publicly rounded to ${cad(result.legacy_reconciliation.legacy_public_rounded_total_cad)}. The audited model is ${cad(result.totals.economic_cost_cad)} because its itemized scope, tax, contingency and owner-labour basis are shown explicitly.</p><p><a class="button secondary" href="${esc(houseCostHrefToArc())}">Carry dwelling assumptions to ARC affordability</a></p></div></div><p class="house-boundary-note"><strong>Ownership boundary:</strong> residents own the dwelling and build equity in it through payment. This does not create ownership or guaranteed appreciation in the underlying land.</p></section><section class="section tinted" id="design"><div class="section-heading"><p class="eyebrow">Design inputs</p><h2>Shape the dwelling</h2><p>Geometry drives quantities. Storey choices add actual envelope, floor structure, stairs, guards and headroom deductions.</p></div><div class="house-control-grid"><div><h3>Size and geometry</h3><div class="controls-row">${houseSelect('house-diameter-preset', 'Diameter preset', [['custom', 'Custom diameter'], ...HOUSE_COST_EVIDENCE.diameter_presets.map((row: any) => [String(row.diameter_m), row.label])], diameterPreset, 'diameterPreset')}${houseInput('house-diameter', 'Yurt diameter', houseCostState.diameter_m, 'm', 'diameter_m', '.001', '3')}${houseInput('house-wall-height', 'Wall height', houseCostState.wall_height_m, 'm', 'wall_height_m', '.1', '1.8')}${houseInput('house-roof-pitch', 'Roof pitch', houseCostState.roof_pitch_degrees, 'degrees', 'roof_pitch_degrees', '1', '10')}${houseInput('house-household-size', 'Household size', houseCostState.household_size, 'people', 'household_size', '1', '1')}${houseSelect('house-layout', 'Layout', layoutOptions, houseCostState.layout, 'layout')}</div><div class="controls-row">${houseInput('house-windows', 'Windows / dome glazing', houseCostState.window_count, 'count', 'window_count', '1', '1')}${houseInput('house-doors', 'Exterior / interior doors', houseCostState.door_count, 'count', 'door_count', '1', '1')}${houseInput('house-partitions', 'Partition loss', houseCostState.partition_loss_fraction * 100, '%', 'partition_loss_percent', '1', '0')}</div></div><div><h3>Construction, servicing and financing</h3><div class="controls-row">${houseSelect('house-band', 'Planning band', houseBandOptions, houseCostState.band, 'band')}${houseSelect('house-labour-mode', 'Construction labour', labourModes, houseCostState.labourMode, 'labourMode')}${houseSelect('house-service-mode', 'Utility package', services, houseCostState.servicingMode, 'servicingMode')}${houseSelect('house-ownership', 'Payment basis', ownershipOptions, houseCostState.ownership, 'ownership')}${houseInput('house-labour-rate', 'Paid labour rate', houseCostState.labourRate, 'CAD/hour', 'labourRate', '1', '0')}${houseInput('house-owner-rate', 'Owner labour value', houseCostState.ownerRate, 'CAD/hour', 'ownerRate', '1', '0')}</div><div class="controls-row">${houseInput('house-tax-rate', 'Tax / HST allowance', houseCostState.taxRate * 100, '%', 'taxRate', '1', '0')}${houseInput('house-contingency-rate', 'Contingency', houseCostState.contingencyRate * 100, '%', 'contingencyRate', '1', '0')}${houseInput('house-down-payment', 'Down payment', houseCostState.downPaymentRate * 100, '%', 'downPaymentRate', '1', '0')}${houseInput('house-interest', 'Interest rate', houseCostState.interestRate * 100, '%', 'interestRate', '.1', '0')}${houseInput('house-amortization', 'Amortization', houseCostState.amortizationYears, 'years', 'amortizationYears', '1', '1')}${houseInput('house-loan-term', 'Loan term / renewal', houseCostState.loanTermYears, 'years', 'loanTermYears', '1', '1')}</div><label class="control house-quote-control"><span>Custom completed-dwelling quote</span><input id="house-custom-quote" data-house-field="customQuote" type="number" min="0" step="1000" value="${houseCostState.customQuote == null ? '' : houseCostState.customQuote}"><em>CAD; optional financing headline</em></label></div></div><div class="house-actions"><button class="button secondary" id="house-reset" type="button">Reset published defaults</button><span class="small-note">Changes are written into this page's shareable query string.</span></div></section><section class="section" id="cost-stack"><div class="section-heading"><p class="eyebrow">Detailed accounting</p><h2>Every component has one scope</h2><p>Package rows show their included labour and fees. Assembly boundaries identify what each construction row includes and excludes.</p></div><div class="metric-grid four">${metric('Materials / non-labour', cad(result.components.reduce((sum: number, row: any) => sum + Number(row.material_cost_cad), 0)), 'before paid labour')}${metric('Paid labour', `${fmt(result.labour.paid_hours, 1)} h`, cad(result.labour.paid_labour_cash_cad))}${metric('Owner labour', `${fmt(result.labour.owner_hours, 1)} h`, `${cad(result.labour.owner_labour_imputed_cad)} imputed`)}${metric('Tax + contingency', cad(result.totals.taxes_cad + result.totals.contingency_cad), 'shown separately')}</div><details class="input-details" open><summary>Component quantities, rates and labour</summary><div class="table-scroll"><table class="evidence-table house-cost-table"><caption>Selected ${esc(result.band)} planning band; edit a rate to test a quote or alternative material package.</caption><thead><tr><th>Component</th><th>Quantity</th><th>Unit</th><th>Rate</th><th>Materials / non-labour</th><th>Total labour</th><th>Cash cost</th><th>Evidence and scope</th></tr></thead><tbody>${rateRows}</tbody></table></div></details><details class="method"><summary>Geometry and usable-area audit</summary><p>${esc(`The ${geometry.inputs.diameter_m} m reference uses full precision internally. ${geometry.headroom.method}`)}</p><div class="metric-grid four">${metric('Footprint', `${fmt(geometry.footprint_m2, 2)} m²`, 'pi × radius²')}${metric('Perimeter', `${fmt(geometry.perimeter_m, 2)} m`, 'pi × diameter')}${metric('Wall envelope', `${fmt(geometry.exterior_wall_area_m2, 2)} m²`, `${fmt(geometry.total_wall_height_m, 2)} m total wall height`)}${metric('Sloping roof area', `${fmt(geometry.roof_sloping_area_m2, 2)} m²`, 'actual pitched surface')}${metric('Gross floor area', `${fmt(geometry.gross_floor_area_m2, 2)} m²`, 'lower + upper floor')}${metric('Usable floor area', `${fmt(geometry.usable_floor_area_m2, 2)} m²`, 'after deductions')}</div><p>Usable area deducts ${fmt(geometry.area_deductions_m2.stair_opening, 2)} m² for stair opening, ${fmt(geometry.area_deductions_m2.interior_partitions, 2)} m² for partitions and ${fmt(geometry.area_deductions_m2.restricted_headroom, 2)} m² for restricted loft headroom. Full two-storey geometry uses a second wall-height envelope; headroom is derived from the pitched roof and upper-floor elevation.</p></details><details class="method"><summary>Construction stages and service boundaries</summary><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Stage</th><th>Cash cost</th><th>Includes</th></tr></thead><tbody><tr><th>Shell</th><td>${cad(result.stages.shell.cash_cost_cad)}</td><td>${esc(result.stages.shell.includes.join(', '))}</td></tr><tr><th>Insulated / heated structure</th><td>${cad(result.stages.insulated_heated_structure.cash_cost_cad)}</td><td>${esc(result.stages.insulated_heated_structure.includes.join(', '))}</td></tr><tr><th>Completed dwelling cash budget</th><td>${cad(result.stages.completed_dwelling.cash_cost_cad)}</td><td>fit-out, utility packages, logistics, design, residual approvals, tax and contingency</td></tr></tbody></table></div><p>ARC household systems are counted once: water/plumbing/sanitation ${cad(water?.package_total_cad)}, hot water ${cad(hotWater?.package_total_cad)} and electrical ${cad(electrical?.package_total_cad)}. The package labour and fees are inside those totals. Choosing centralized servicing removes those dwelling components and exposes the unresolved shared quote in the servicing record.</p></details></section><section class="section tinted" id="sensitivity"><div class="section-heading"><p class="eyebrow">Thresholds and comparisons</p><h2>Size and layout do not scale perfectly smoothly</h2><p>Some costs rise continuously with area or perimeter. Others jump when an upper floor, larger span or higher-pitch roof changes the structural design.</p></div><div class="house-bars" role="img" aria-label="Completed dwelling economic cost by yurt diameter. The table below provides the accessible text equivalent.">${diameterBars}</div><div class="table-scroll"><table class="evidence-table house-sensitivity-table"><caption>Diameter sensitivity at the selected labour, servicing and financing assumptions</caption><thead><tr><th>Diameter</th><th>Usable area</th><th>Economic cost</th><th>Cost per usable m²</th><th>Thresholds</th></tr></thead><tbody>${diameterRows}</tbody></table></div><div class="table-scroll"><table class="evidence-table house-sensitivity-table"><caption>Alternative layouts at the selected diameter</caption><thead><tr><th>Layout</th><th>Usable area</th><th>Economic cost</th><th>Cost per usable m²</th><th>Owner hours</th><th>Paid hours</th></tr></thead><tbody>${layoutRows}</tbody></table></div><details class="method"><summary>Threshold rule audit</summary><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Rule</th><th>Trigger</th><th>State</th><th>Confidence</th><th>Evidence / note</th></tr></thead><tbody>${thresholdRows}</tbody></table></div><p>Thresholds are planning triggers, not structural approval rules. Diameter, span, snow and wind loads, foundations, connections and fire/life-safety details require qualified design confirmation.</p></details><div class="metric-grid three">${metric('Low planning band', cad(bands.low.totals.completed_dwelling_capital_cad), 'component rates, tax and contingency')}${metric('Central planning band', cad(bands.central.totals.completed_dwelling_capital_cad), 'selected reference')}${metric('High planning band', cad(bands.high.totals.completed_dwelling_capital_cad), 'component rates, tax and contingency')}</div><p class="small-note">The current low-to-high completed economic cost range is ${houseMoneyRange(bands)}. It is not an installed quotation.</p></section><section class="section" id="evidence"><div class="section-heading"><p class="eyebrow">Method and evidence</p><h2>What is included, and what still needs confirmation?</h2><p>Geometry and utility design boundaries are carried forward from Living Region's ARC work. Prices, threshold effects and local approval outcomes remain visible planning inputs.</p></div><div class="house-evidence-grid"><div><h3>Known boundaries</h3><ul><li>Resident-owned dwelling capital is separate from land and ARC site lease economics.</li><li>Household utility systems are counted once; centralized alternatives move their capital outside this result.</li><li>Owner-builder work reduces cash expenditure but remains visible as hours and imputed value.</li><li>Land purchase, site lease, shared infrastructure, maintenance reserves and household operating costs are excluded.</li></ul><p><a href="${appUrl('/carrying-capacity')}" data-nav>See the carrying-capacity model</a> for food, land and heating requirements.</p></div><div><h3>Evidence gaps</h3><ul><li>Full structural engineering for diameter, roof pitch, snow, wind, foundation and anchorage.</li><li>Installed supplier quotes for a four-season Canadian yurt package and local delivery.</li><li>Municipal permit, development-charge, plumbing and sewage approvals.</li><li>HST treatment, owner-builder eligibility and any rebate.</li><li>Kitchen and bathroom fit-out allowances remain unitemized planning values outside utility fixtures.</li></ul><p>The selected result is a transparent planning estimate. Configurations with upper floors, nonstandard servicing or a custom quote require supplier, municipal and engineering confirmation.</p></div></div><details class="method" open><summary>Source and status register</summary><div class="source-list">${sourceRows}</div></details><details class="method" open><summary>ARC benchmark and former-model reconciliation</summary><p>The historical exact integrated benchmark is ${cad(result.legacy_reconciliation.legacy_exact_integrated_total_cad)}, publicly rounded to ${cad(result.legacy_reconciliation.legacy_public_rounded_total_cad)}. The former component model produced ${cad(bridge.former_model_economic_capital_cad)} economic cost. The audited result is ${cad(bridge.corrected_economic_capital_cad)}; the bridge is direct cash ${cad(bridge.direct_cash_delta_cad)}, tax ${cad(bridge.tax_delta_cad)}, contingency ${cad(bridge.contingency_delta_cad)} and owner labour ${cad(bridge.owner_labour_delta_cad)}.</p><div class="table-scroll"><table class="evidence-table"><caption>Original, former and audited package rows</caption><thead><tr><th>Component</th><th>Original scope / amount</th><th>Former model</th><th>Audited scope / amount</th><th>Delta</th></tr></thead><tbody>${bridgeRows}</tbody></table></div><p>${esc(bridge.explanation)}</p></details><p><a class="button secondary" href="${esc(houseCostHrefToArc())}">Open ARC affordability with these dwelling assumptions</a></p><p><a class="back-top" href="#top">Back to top</a></p></section>`, 'house');
}
function renderFoodSectionNew(result: any) { const food = result.custom.food; const nutrient = result.custom.nutrient_food_system ?? {}; return `<section class="section" id="food"><div class="section-heading"><p class="eyebrow">04 · food requirement</p><h2>People → food energy → food area</h2><p>The person variables determine food energy through the canonical Health Canada equation. They do not determine agricultural labour capacity.</p></div><div class="metric-grid four">${metric('Household food energy', energy(result.demand), 'Health Canada EER total')}${metric('Food-production area', area(result.custom.food_area_ha), 'Balanced low-input system')}${metric('Food-adult-equivalent', `${fmt(result.custom.food_adult_equivalents, 2)} FAE`, 'Food-energy normalization only')}${metric('Total protein screen', nutrient.protein_adequacy ? 'RDA met' : 'Deficit', `${fmt(nutrient.protein_coverage_ratio * 100, 0)}% of Health Canada RDA`)}</div>${renderEnergy(result)}<details class="input-details"><summary>Adjust household members</summary><div class="member-list">${state.members.map(renderMember).join('')}</div><button class="button secondary" data-action="add-member">+ Add household member</button></details></section>`; }

function renderB12Comparison(b12Goal: any) {
  const systems = b12Goal.system_comparison ?? {};
  const labels: Record<string, string> = {rabbit_meat: 'Rabbits', chicken_eggs: 'Heritage chickens', goose_meat: 'Geese', mixed_rabbit_eggs: 'Rabbits + chickens'};
  const populationLabel = (id: string, row: any) => {
    if (!row) return 'No feasible population in search range';
    if (id === 'mixed_rabbit_eggs') return `${fmt(row.rabbit_does, 0)} does + ${fmt(row.chicken_hens, 0)} hens`;
    const femaleLabel = id === 'chicken_eggs' ? 'hens' : id === 'goose_meat' ? 'females' : 'does';
    const maleLabel = id === 'chicken_eggs' ? 'roosters' : id === 'goose_meat' ? 'males' : 'bucks';
    return `${fmt(row.breeding_females, 0)} ${femaleLabel} + ${fmt(row.breeding_males, 0)} ${maleLabel}`;
  };
  const option = (id: string, row: any, metric: string) => {
    if (!row) return '—';
    if (metric === 'population') return populationLabel(id, row);
    if (metric === 'land') return area(row.food_feed_area_ha);
    if (metric === 'labour') return `${fmt(row.labour_hours_year, 0)} h/year`;
    return `${fmt(row.human_edible_feed_protein_kg_year, 1)} kg protein/year`;
  };
  const rows = Object.entries(systems).filter(([, row]: any) => row.minimum_population || row.lowest_land || row.lowest_labour || row.lowest_human_edible_feed);
  if (!rows.length) return '';
  return `<details class="method b12-comparison"><summary>Compare property-produced ways to meet B12</summary><p class="small-note">Each row is searched as a discrete self-replacing population with zero purchased feed. The first feasible population, lowest-land, lowest-labour and lowest-human-edible-feed choices can differ; no animal system is declared universally optimal.</p><div class="table-scroll"><table class="evidence-table"><thead><tr><th>System</th><th>First feasible population</th><th>Lowest land</th><th>Lowest labour</th><th>Lowest human-edible feed</th></tr></thead><tbody>${rows.map(([id, row]: any) => `<tr><th scope="row">${esc(labels[id] ?? id)}</th><td>${option(id, row.minimum_population, 'population')}</td><td>${option(id, row.lowest_land, 'land')}<br><small>${row.lowest_land ? `${fmt(row.lowest_land.b12_coverage_ratio * 100, 0)}% B12` : ''}</small></td><td>${option(id, row.lowest_labour, 'labour')}</td><td>${option(id, row.lowest_human_edible_feed, 'feed')}</td></tr>`).join('')}</tbody></table></div></details>`;
}

function renderNutrientCompleteness(nutrient: any) {
  const complete = nutrient.nutrient_completeness ?? {};
  const pattern = complete.amino_acid_pattern ?? {};
  const limiting = pattern.limiting_pattern_amino_acid ?? pattern.limiting_amino_acid;
  const lysine = pattern.rows?.lysine ?? {};
  const micro = Object.entries(complete.nutrients ?? {}).filter(([, row]: any) => row.status !== 'adequate from property-produced food').map(([id, row]: any) => `${id}: ${row.status}`).join(' · ') || 'Key tracked nutrients adequate in the current food-form evidence';
  const count = Number(nutrient.livestock_system_count ?? 0);
  const scale = Number(nutrient.livestock_scale ?? 0);
  const countLabel = count === 0 ? '0 selected systems' : `${fmt(count, 0)} selected system${count === 1 ? '' : 's'} · scale ${fmt(scale, 2)}`;
  const goals = Object.entries(state.contract.nutrition?.goals ?? {}).map(([id, goal]: any) => [id, goal.label] as [string, string]);
  const iron = complete.iron_assessment ?? {};
  const resolution = nutrient.nutrition_goal_resolution;
  const b12Goal = nutrient.minimum_property_b12 ?? {};
  const b12Candidate = b12Goal.system_comparison?.rabbit_meat?.minimum_population;
  const b12Comparison = renderB12Comparison(b12Goal);
  const pregnancyRows = nutrient.pregnancy_sensitivity_comparison ?? [];
  const pregnancyTable = pregnancyRows.length ? `<details class="method"><summary>Pregnancy iron sensitivity comparison</summary><p class="small-note">Subject: ${esc(nutrient.pregnancy_sensitivity_subject?.label ?? 'selected sensitivity member')} · ${esc(nutrient.pregnancy_sensitivity_subject?.basis ?? '')}. This is a planning comparison, not clinical or prenatal advice.</p><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Food system</th><th>Total iron</th><th>Heme iron</th><th>Absorbable range</th><th>Coverage</th><th>Food/feed land</th><th>Livestock labour</th></tr></thead><tbody>${pregnancyRows.map((row: any) => `<tr><th scope="row">${esc(row.label)}</th><td>${fmt(row.total_iron_mg_year, 0)} mg/year</td><td>${row.heme_iron_mg_year == null ? 'Unresolved' : `${fmt(row.heme_iron_mg_year, 0)} mg/year`}</td><td>${row.estimated_absorbable_iron_mg_year == null ? 'Unresolved' : esc(String(row.estimated_absorbable_iron_mg_year))}</td><td>${fmt(row.iron_coverage_ratio == null ? null : row.iron_coverage_ratio * 100, 0)}%</td><td>${area(row.food_feed_area_ha)}</td><td>${fmt(row.labour_hours_year, 0)} h/year</td></tr>`).join('')}</tbody></table></div></details>` : '';
  return `<div class="nutrition-controls controls-row">${selectControl('nutrition-goal', 'Nutrition objective', goals, state.nutritionGoal)}</div><p class="small-note">Goal resolution: <strong>${esc(resolution?.label ?? 'User-selected animal-food share')}</strong> → ${esc(nutrient.mode ?? 'plants_only')}, ${fmt(nutrient.livestock_scale ?? 0, 2)} livestock scale. The livestock mode selector remains available for the user-selected objective; other goals apply their stated mode automatically.</p><div class="metric-grid four">${metric('Protein-quality pattern', limiting ?? 'Unresolved', limiting ? `${fmt((lysine.quality_pattern_ratio ?? lysine.adequacy_ratio ?? 0) * 100, 0)}% reference-pattern score` : 'No defensible profile')}${metric('Absolute amino-acid adequacy', pattern.absolute_adequacy ? 'Modeled requirements met' : 'Deficit / unresolved', lysine.absolute_adequacy_ratio == null ? 'No household requirement' : `lysine ${fmt(lysine.absolute_adequacy_ratio * 100, 0)}% of derived requirement`)}${metric('B12', complete.nutrients?.b12?.status ?? 'Unresolved', `${fmt((complete.nutrients?.b12?.adequacy_ratio ?? 0) * 100, 0)}% of annual DRI`)}${metric('External / unresolved', complete.external_inputs?.length ? `${complete.external_inputs.length} tracked` : 'None', micro)}${metric('Livestock system', countLabel, nutrient.livestock_scaling_basis === 'explicit_sensitivity_override' ? 'explicit scale override' : 'one selected system resized to household demand')}</div>${b12Candidate ? `<p class="small-note">Minimum property-B12 search: first feasible rabbit population is ${fmt(b12Candidate.breeding_females, 0)} does + ${fmt(b12Candidate.breeding_males, 0)} buck${b12Candidate.breeding_males === 1 ? '' : 's'}, producing ${fmt(b12Candidate.harvest_animals, 0)} harvest animals and ${fmt(b12Candidate.b12_coverage_ratio * 100, 0)}% B12 coverage.</p>` : ''}${b12Comparison}${renderWholeDietNutrition(nutrient)}${pregnancyTable}<p class="small-note">Iron: ${fmt(iron.total_food_iron_mg_year, 0)} mg/year food iron; bioavailable fraction and heme contribution remain unresolved. ${complete.nutrients?.b12?.status === 'small external input required' ? 'B12 remains an external non-food input in this scenario.' : ''}</p>`;
}
function renderSuccessionNutrition(nutrient: any) { const ledger = nutrient.food_succession_ledger ?? {}; const rows = ledger.rows ?? []; if (!rows.length) return ''; const fatIds = new Set(['hazelnut_dried', 'black_walnut_dried', 'sunflower_seed_dry']); const sourceText = (row: any) => { const sources = (row.foods ?? []).filter((food: any) => fatIds.has(food.composition_id) && Number(food.consumed_food_kg_year ?? 0) > 0).map((food: any) => `${food.label ?? food.composition_id} ${fmt(food.consumed_food_kg_year, 1)} kg`).join(' · '); return sources || 'No principal nut/oilseed source'; }; const externalText = (row: any) => { const items = (row.external_inputs ?? []).map((item: any) => item.nutrient).slice(0, 3); return items.length ? items.join(', ') : 'None shown'; }; return `<details class="method succession-panel" open><summary>Food-forest succession and whole-diet nutrition by year</summary><p class="small-note">The headline macro result is year-specific. This ledger uses the same perennial bearing curves that size the food land: annual bridge crops contract as retained perennial harvest becomes available, while unconsumed harvest is reported as surplus rather than forced into the household diet.</p><div class="table-scroll"><table class="evidence-table succession-table"><thead><tr><th>Year</th><th>Carb / protein / fat</th><th>Food energy source</th><th>Annual cultivation</th><th>Occupied food area</th><th>Surplus</th><th>Major fat source</th><th>External / limiting</th></tr></thead><tbody>${rows.map((row: any) => { const macro = row.macro_summary ?? {}; const p = macro.energy_percent ?? {}; const limit = row.amino_acid_pattern?.limiting_amino_acid ?? '—'; const fatFloor = macro.flags?.children_fat_floor_met === false ? ' · child fat floor' : ''; return `<tr><th scope="row">${row.year === 'mature' ? 'Mature' : `Year ${esc(row.year)}`}</th><td>${fmt(p.carbohydrate, 1)}% / ${fmt(p.protein, 1)}% / ${fmt(p.fat, 1)}%${fatFloor ? `<br><span class="status constrained">${esc(fatFloor.trim())}</span>` : ''}</td><td>${fmt(row.annual_food_energy_gj_year, 1)} annual · ${fmt(row.perennial_food_energy_consumed_gj_year, 1)} perennial · ${fmt(row.animal_food_energy_gj_year, 1)} animal GJ</td><td>${fmt(row.annual_cultivation_area_ha, 3)} ha</td><td>${fmt(row.occupied_food_production_area_ha, 3)} ha</td><td>${fmt(row.exportable_surplus_food_energy_gj_year, 1)} GJ</td><td>${esc(sourceText(row))}</td><td>${esc(externalText(row))}${limit !== '—' ? `<br>pattern: ${esc(limit)}` : ''}</td></tr>`; }).join('')}</tbody></table></div><p class="small-note">Ratios are calculated from consumed food only. Produced harvest is separately allocated to household consumption, losses, reserves, livestock feed and exportable surplus. Annual cultivation is the bridge requirement for that selected year, not a permanent mature-ration assumption.</p></details>`; }
function renderWholeDietNutrition(nutrient: any) { const diet = nutrient.nutrient_completeness?.whole_diet ?? {}; const macros = diet.macros ?? {}; const pctEnergy = macros.energy_percent ?? {}; const portfolioLand = diet.portfolio_land ?? {}; const marginal = nutrient.marginal_nutrient_value ?? {}; const rows = Object.entries(marginal.rows ?? {}).filter(([id]) => ['b12', 'd', 'a', 'iron', 'zinc', 'calcium', 'selenium', 'choline', 'alpha_linolenic_g'].includes(id)); return `<div class="whole-diet-panel"><h3>Whole-diet adequacy and marginal value</h3><div class="metric-grid four">${metric('Carbohydrate', `${fmt(pctEnergy.carbohydrate, 1)}% energy`, `${fmt(macros.grams_per_day?.carbohydrate, 1)} g/day`)}${metric('Protein', `${fmt(pctEnergy.protein, 1)}% energy`, `${fmt(macros.grams_per_day?.protein, 1)} g/day`)}${metric('Fat', `${fmt(pctEnergy.fat, 1)}% energy`, `${fmt(macros.grams_per_day?.fat, 1)} g/day`)}${metric('Fibre', `${fmt(macros.grams_per_day?.fibre, 1)} g/day`, macros.flags?.fat_share_status ?? 'AMDR screening')}</div><p class="small-note">Household AMDR intersection: protein ${fmt(macros.amdr?.household_intersection?.protein_percent_energy?.min, 0)}–${fmt(macros.amdr?.household_intersection?.protein_percent_energy?.max, 0)}%, fat ${fmt(macros.amdr?.household_intersection?.fat_percent_energy?.min, 0)}–${fmt(macros.amdr?.household_intersection?.fat_percent_energy?.max, 0)}%, carbohydrate ${fmt(macros.amdr?.household_intersection?.carbohydrate_percent_energy?.min, 0)}–${fmt(macros.amdr?.household_intersection?.carbohydrate_percent_energy?.max, 0)}%. ${macros.flags?.children_fat_floor_met === false ? 'The current fat share is below the highest child fat floor.' : 'The current fat share meets the modeled child floor.'}</p><p class="small-note">Portfolio: ${fmt(diet.portfolio_energy_share * 100, 0)}% of plant food energy is represented by carotenoid-rich vegetables, leafy greens, fruit, berries and perennial fat sources. Required portfolio areas are allocated inside the existing food zones where capacity allows; current additional area is ${area(portfolioLand.additional_area_ha)}. Bearing curves keep non-bearing perennial output out of early-year food credit.</p>${renderSuccessionNutrition(nutrient)}<details class="method"><summary>Marginal contribution of selected animal foods</summary><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Nutrient</th><th>Before livestock</th><th>After livestock</th><th>Coverage gained</th></tr></thead><tbody>${rows.map(([id, row]: any) => `<tr><th scope="row">${esc(id.replaceAll('_', ' '))}</th><td>${fmt(row.before_coverage_ratio == null ? null : row.before_coverage_ratio * 100, 0)}%</td><td>${fmt(row.after_coverage_ratio == null ? null : row.after_coverage_ratio * 100, 0)}%</td><td>${fmt(row.coverage_gained == null ? null : row.coverage_gained * 100, 1)} percentage points</td></tr>`).join('')}</tbody></table></div><p class="small-note">Selected animal food: ${fmt(marginal.animal_food_kg_year, 1)} kg/year · ${fmt(marginal.animal_energy_share_percent, 1)}% of dietary energy · ${fmt(marginal.extra_feed_land_ha, 3)} ha dedicated feed land · ${fmt(marginal.labour_hours_year, 0)} labour hours/year · ${fmt(marginal.human_edible_feed_protein_kg_year, 1)} kg human-edible feed protein consumed.</p></details></div>`; }
function renderLivestockLedger(nutrient: any, protein: any) { const labourScaling = state.contract.livestock?.labour_scaling ?? {}; return `<div class="livestock-ledger"><h3>Actual livestock scale</h3><p class="small-note">The selected system is resized to household food demand. Breeding animals are discrete; reproductive output, care and processing use the same actual animal counts.</p>${(nutrient.animals ?? []).map((row: any) => { const population = row.population ?? {}; const reproduction = row.reproduction ?? {}; const product = row.output?.eggs_kg_year != null ? `${fmt(row.output.eggs_kg_year, 1)} kg eggs` : `${fmt(row.output?.edible_meat_kg_year, 1)} kg edible meat`; const surviving = population.kits_surviving_year ?? population.chicks_hatched_and_surviving_year ?? population.goslings_hatched_and_surviving_year ?? population.kids_surviving_year; const harvest = population.animals_available_for_harvest_year ?? population.surplus_males_year; const proteinShare = Number(protein.household_protein_kg_year ?? 0) > 0 ? Number(row.output?.edible_protein_kg_year ?? 0) / Number(protein.household_protein_kg_year) * 100 : 0; return `<div class="component-detail"><h4>${esc(row.label)}</h4><p><strong>Animals:</strong> ${fmt(reproduction.breeding_females ?? 0, 0)} breeding females · ${fmt(reproduction.breeding_males ?? 0, 0)} breeding males${population.production_animals_year == null ? '' : ` · ${fmt(population.production_animals_year, 0)} production animals/year`}</p><p><strong>Annual output:</strong> ${surviving == null ? '' : `${fmt(surviving, 0)} surviving offspring · `}${harvest == null ? '' : `${fmt(harvest, 1)} available for harvest · `}${product} · ${fmt(row.output?.edible_protein_kg_year, 2)} kg animal protein (${fmt(proteinShare, 0)}% of household requirement)</p><p><strong>Replacements:</strong> ${fmt(reproduction.replacement_females_year ?? 0, 2)} females/year · ${fmt(reproduction.replacement_males_year ?? 0, 2)} males/year</p><p><strong>Labour:</strong> ${fmt(row.labour?.recurring_hours_year, 0)} recurring · ${fmt(row.labour?.slaughter_processing_hours_year, 0)} processing · ${fmt(row.labour?.total_hours_year, 0)} total hours/year · ${fmt(row.labour?.hours_per_kg_edible_product, 2)} hours/kg edible product · ${fmt(row.labour?.hours_per_kg_animal_protein, 2)} hours/kg animal protein</p></div>`; }).join('')}<p class="small-note"><strong>Labour scaling:</strong> ${esc(labourScaling.note ?? 'Labour is calculated from explicit task assumptions.')} Formula: ${esc(labourScaling.formula ?? 'task components plus processing setup and per-animal work')}.</p></div>`; }
function renderLivestockSectionNew(result: any) { const nutrient = result.custom.nutrient_food_system ?? {}; const protein = result.custom.protein_demand ?? {}; const modeOptions: Array<[string, string]> = [['plants_only', 'Plants only'], ['rabbit_meat', 'Rabbit'], ['chicken_eggs', 'Self-replacing chicken flock'], ['chicken_meat', 'Fast-growing chicken sensitivity'], ['goose_meat', 'Goose'], ['goat_meat', 'Goat'], ['mixed_rabbit_eggs', 'Rabbit + chicken flock']]; const rationOptions = Object.entries(state.contract.livestock?.ration_scenarios ?? {}).map(([id, row]: any) => [id, row.label] as [string, string]); const feed = nutrient.feed ?? {}; const external = state.livestockRation !== 'arc_integrated'; const animal = (nutrient.animals ?? []).map((row: any) => `${esc(row.label)}: ${fmt(row.output?.edible_protein_kg_year, 1)} kg protein/year`).join(' · ') || 'No livestock selected'; return `<section class="section tinted" id="food-protein"><div class="section-heading"><p class="eyebrow">Food and protein system</p><h2>Plants first, livestock only where it helps</h2><p>ARC livestock scenarios grow all dietary feed on the property. Shortfalls become dedicated feed hectares or make the option infeasible; they are never silently covered by imported feed. Canonical livestock must also reproduce on site.</p></div><div class="controls-row">${selectControl('livestock-mode', 'Food system mode', modeOptions, state.livestockMode)}${selectControl('livestock-ration', 'Ration scenario', rationOptions, state.livestockRation)}</div><div class="metric-grid four">${metric('Energy adequacy', nutrient.energy_adequacy ? 'Meets modeled demand' : 'Deficit', `${energy(nutrient.plant_energy_demand_gj_year ?? 0)} plant + ${energy(nutrient.animal_food_energy_gj_year ?? 0)} animal`)}${metric('Protein requirement', `${fmt(protein.household_protein_g_day, 1)} g/day`, `${fmt(protein.household_protein_kg_year, 1)} kg/year RDA`)}${metric('Plant protein', `${fmt(nutrient.plant_protein_kg_year, 1)} kg/year`)}${metric('Animal protein', `${fmt(nutrient.animal_protein_kg_year, 1)} kg/year`, animal)}${metric('Protein adequacy', nutrient.protein_adequacy ? 'Meets modeled RDA' : 'Deficit', `${fmt(nutrient.protein_coverage_ratio * 100, 0)}% of RDA`)}</div>${renderNutrientCompleteness(nutrient)}<div class="metric-grid four">${metric('Feed self-sufficiency', nutrient.feed_self_sufficiency ? 'Property supplied' : 'Not feasible', nutrient.feed_self_sufficiency ? 'No feed-energy/protein import' : `${fmt(feed.feed_deficit_dm_kg_year, 0)} kg DM unresolved`)}${metric('Reproductive self-sufficiency', nutrient.reproductive_self_sufficiency ? 'On-site replacement' : nutrient.mode === 'plants_only' ? 'No livestock' : 'Not canonical', nutrient.mode === 'plants_only' ? 'Plants-only baseline' : 'No recurring chicks or production animals')}${metric('Dedicated feed land', area(feed.additional_dedicated_feed_land_ha), 'added to productive land')}${metric('Winter stored feed', `${fmt(feed.winter_stored_feed_available_kg, 0)} / ${fmt(feed.winter_stored_feed_required_kg, 0)} kg DM`, `storage loss ${fmt(feed.storage_loss_kg_year, 0)} kg`)}</div><div class="metric-grid four">${metric('Human-edible feed', `${fmt(feed.human_edible_feed_protein_consumed_kg, 1)} kg protein`, 'consumed by animals')}${metric('Human-inedible feed', `${fmt(feed.human_inedible_feed_dm_kg, 0)} kg DM`, 'forage, browse, residues and similar streams')}${metric('Recurring livestock care', `${fmt(nutrient.labour?.recurring_hours_year, 0)} hours/year`, 'task-based planning model')}${metric('Slaughter / processing', `${fmt(nutrient.labour?.slaughter_processing_hours_year, 0)} hours/year`, 'setup + per-animal work')}</div>${renderLivestockLedger(nutrient, protein)}<p class="small-note">Protein-quality pattern score is separate from absolute amino-acid adequacy, and both remain separate from digestibility-adjusted quality. ${external ? 'This external-feed sensitivity is not ARC carrying-capacity compliant.' : 'Canonical feed energy and protein imports remain zero.'}</p></section>`; }
function renderHeatingSectionNew(result: any) { const heating = result.custom.heating; return `<section class="section tinted" id="heating"><div class="section-heading"><p class="eyebrow">05 · heating</p><h2>Buildings → useful heat → woody land</h2><p>Building geometry, envelope, leakage and heater efficiency determine the winter heat load. Each heated building is calculated separately and then summed.</p></div><div class="metric-grid three">${metric('Useful heat', energy(heating.total_useful_heat_gj_year), 'All heated buildings')}${metric('Gross woody energy', energy(heating.total_gross_wood_energy_gj_year), 'Heater efficiency included')}${metric('Woody hectares', area(result.custom.heating_area_ha), 'Selected site productivity')}</div><details class="input-details"><summary>Adjust heated buildings and envelope assumptions</summary>${renderBuildings(result)}</details><details class="input-details"><summary>Check assigned labour capacity</summary>${renderLabour(result)}</details></section>`; }
function annualCropStatusNew(row: any, result: any) { const rule = state.contract.site_classes[state.site].local_environment?.annual_crops?.[row.id]; const selected = result.custom.food?.rows?.find((candidate: any) => candidate.id === row.id); if (rule?.viable === false) return {label: 'Excluded', className: 'excluded', yield: null, role: 'Unsuitable for selected site band'}; if (selected) return {label: 'Selected', className: 'selected', yield: selected.food_gj_ha, role: `${fmt(selected.energy_share * 100, 0)}% of balanced energy mix`}; return {label: 'Viable alternative', className: 'alternative', yield: row.food_gj_ha * Number(rule?.yield_multiplier ?? 1), role: 'Not used in current balanced mix'}; }
function renderAnnualCropsSectionNew(result: any) { const rows = state.contract.food_energy_evidence.rows; return `<section class="section" id="annual-crops"><div class="section-heading"><p class="eyebrow">06 · annual crops</p><h2>Compact annual-crop evidence</h2><p>Annual rows support the bridge while perennial systems establish. Status and effective yield are specific to the selected site band.</p></div><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Crop</th><th>Site status</th><th>Effective yield</th><th>Role</th><th>Evidence</th></tr></thead><tbody>${rows.map((row: any) => { const status = annualCropStatusNew(row, result); return `<tr><th scope="row">${esc(row.crop)}</th><td><span class="status ${status.className}">${status.label}</span></td><td>${status.yield == null ? '—' : `${fmt(status.yield, 1)} GJ/ha`}</td><td>${esc(status.role)}</td><td><details><summary>View</summary><p>${esc(row.category ?? '')} · ${esc(row.evidence_type ?? row.canonical_status ?? 'Evidence row')}</p><p>${sourceLinks(row.source)}</p></details></td></tr>`; }).join('')}</tbody></table></div><p class="small-note">Selected means the row participates in the current balanced food-energy mix. Viable alternatives remain biologically available but are not silently added to the mix.</p><a class="back-top" href="#top">Back to top</a></section>`; }
function perennialStatusNew(row: any) { const capability = state.contract.site_classes[state.site].local_environment?.perennial_layers?.[row.id]; const selected = state.contract.establishment.site_models?.[state.site]?.perennial_mix?.some((candidate: any) => candidate.id === row.id); if (capability?.viable === false) return {label: 'Excluded', className: 'excluded'}; if (String(row.evidence_status).toLowerCase().includes('reference')) return {label: 'Reference only', className: 'reference'}; if (selected) return {label: 'Central synthesis', className: 'selected'}; return {label: 'Viable alternative', className: 'alternative'}; }
function renderPerennialSectionNew() { const evidence = state.contract.perennial_food_evidence; return `<section class="section tinted" id="perennial-crops"><div class="section-heading"><p class="eyebrow">07 · perennial crops</p><h2>Compact perennial evidence</h2><p>These systems provide the mature mix and establish at different rates. Reference-only candidates remain visible without receiving fabricated canonical yields.</p></div><div class="table-scroll"><table class="evidence-table perennial-table"><thead><tr><th>Crop/system</th><th>Model status</th><th>First crop</th><th>Substantial crop</th><th>Mature</th><th>Mature yield</th></tr></thead><tbody>${evidence.rows.map((row: any) => { const status = perennialStatusNew(row); return `<tr><th scope="row">${esc(row.species)}</th><td><span class="status ${status.className}">${status.label}</span></td><td>${row.first_meaningful_crop_year ? `Year ${esc(row.first_meaningful_crop_year)}` : '—'}</td><td>${row.substantial_crop_year ? `Year ${esc(row.substantial_crop_year)}` : '—'}</td><td>${row.mature_year ? `Year ${esc(row.mature_year)}` : '—'}</td><td>${row.mature_yield_t_ha_year == null ? 'Not reported' : `${fmt(row.mature_yield_t_ha_year, 2)} t/ha`}</td></tr><tr class="evidence-detail"><td colspan="6"><details><summary>Evidence and role</summary><p><strong>Role:</strong> ${esc(row.model_role)} · <strong>Food energy:</strong> ${row.mature_food_gj_ha_year == null ? 'Not reported' : `${fmt(row.mature_food_gj_ha_year, 2)} GJ/ha/year`} · <strong>Macros:</strong> ${row.protein_kg_ha == null ? 'Not reported' : `${fmt(row.protein_kg_ha, 1)} protein / ${fmt(row.fat_kg_ha, 1)} fat / ${fmt(row.carbohydrate_kg_ha, 1)} carbohydrate kg/ha`}</p><p>${esc(row.evidence_type)} · ${esc(row.notes)} · ${sourceLinks(row.source)}</p></details></td></tr>`; }).join('')}</tbody></table></div><div class="mix-panel"><h3>Current canonical mature mix</h3><p>${esc(evidence.central_mix.composition)}</p><div class="mix-bar">${evidence.mix.map((row: any) => `<span style="width:${row.area_share * 100}%" title="${esc(row.species)}">${esc(row.species)}</span>`).join('')}</div><div class="metric-grid four">${metric('Mature mix food energy', `${fmt(evidence.central_mix.mature_food_gj_ha_year, 2)} GJ/ha/year`)}${metric('Protein', `${fmt(evidence.central_mix.protein_kg_ha, 1)} kg/ha`)}${metric('Fat', `${fmt(evidence.central_mix.fat_kg_ha, 1)} kg/ha`)}${metric('Carbohydrate', `${fmt(evidence.central_mix.carbohydrate_kg_ha, 1)} kg/ha`)}</div></div><details class="input-details"><summary>Show mature mix timeline and research updates</summary>${renderPerennialTimeline()}<div class="research-updates">${(evidence.research_updates ?? []).map((row: any) => `<p><strong>${esc(row.species)}</strong> · ${esc(row.evidence_status)} · <a href="${esc(row.source)}" target="_blank" rel="noreferrer">source</a><br>${esc(row.finding)} <b>Model action:</b> ${esc(row.canonical_action)}</p>`).join('')}</div></details><a class="back-top" href="#top">Back to top</a></section>`; }
function renderMethodSectionNew() { return `<section class="section" id="method"><div class="section-heading"><p class="eyebrow">08 · method & sources</p><h2>How to read the model</h2><p>The page follows the dependency chain from answer to components to evidence. The calculations remain in the carrying-capacity package; this browser presents its generated contract.</p></div>${renderEnvironment()}<div class="parallel-chain"><div><p class="eyebrow">People</p><strong>age · sex · height · weight · activity</strong><span>→ MJ/day → GJ/year food → food-production area</span></div><div><p class="eyebrow">Buildings</p><strong>floor area · form · RSI · leakage</strong><span>→ GJ/year useful heat → woody-production area</span></div><div><p class="eyebrow">Combined result</p><strong>food + heat + reserve</strong><span>→ peak establishment and mature land requirements</span></div></div><div class="solar-method"><h3>Solar energy is the underlying budget</h3><p>Solar radiation supports photosynthesis, plant biomass, edible food energy and woody fuel. Local numerical solar availability remains unresolved; the model does not invent an insolation value or photosynthetic efficiency.</p><div class="solar-flow"><span>sunlight</span><b>→</b><span>photosynthesis</span><b>→</b><span>edible food energy</span><b>→</b><span>human metabolism</span></div><div class="solar-flow wood"><span>sunlight</span><b>→</b><span>woody biomass</span><b>→</b><span>stored fuel</span><b>→</b><span>winter heat</span></div></div><details class="method" open><summary>Sources, assumptions and uncertainty</summary><div class="source-list">${state.contract.sources.map((source: any) => `<p><strong>${esc(source.institution)} · ${esc(source.title)}</strong><br><span>${esc(source.evidence_status)}</span> · <a href="${esc(source.url)}" target="_blank" rel="noreferrer">source / evidence file</a></p>`).join('')}</div><p class="small-note">Public energy and thermal quantities are metric/SI. Soil capability is a regional scenario framework, not parcel-level mapping. The generated contract retains evidence status and source provenance for detailed rows.</p></details><a class="back-top" href="#top">Back to top</a></section>`; }
function agroecosystemPlanForUi(): any {
  const agro = state.contract.agroecosystem;
  if (!agro) return null;
  const household = householdResult();
  return calculateAgroecosystemPlan({database: {records: agro.records}, siteId: state.site, siteOverrides: {excluded_species: state.agroExcludedSpecies}, objectives: [state.agroObjective], supportPlantRatio: state.agroSupportRatio, annualAreaHa: 1, perennialAreaHa: 1, nutritionProfiles: state.contract.nutrition.food_profiles, householdPeople: state.members.length, householdFoodDemandGJYear: household.demand, annualResilienceFloorGJYear: household.demand * .1, humanure: {enabled: state.agroHumanure}, selectedSpecies: state.agroSelectedSpecies});
}
function renderMacroConstraintPanel(plan: any, selectedYearDiet: any) {
  const constraint = selectedYearDiet?.nutrition_constraint ?? plan.nutrition_constraint?.years?.find((row: any) => row.year === selectedYearDiet?.year) ?? {};
  const checks = constraint.checks ?? constraint.constraints ?? {};
  const labels: Record<string, string> = {carbohydrate: 'Carbohydrate', protein: 'Protein', fat: 'Fat'};
  const rows = Object.entries(checks).map(([id, row]: any) => {
    const achieved = Number(row.achieved_percent ?? selectedYearDiet?.macro?.energy_percent?.[id]);
    const min = Number(row.min_percent ?? row.min);
    const max = Number(row.max_percent ?? row.max);
    const delta = achieved < min ? `below by ${fmt(min - achieved, 2)} percentage points` : achieved > max ? `above by ${fmt(achieved - max, 2)} percentage points` : 'within target';
    const icon = achieved >= min && achieved <= max ? '✓' : '×';
    return `<tr><th scope="row">${labels[id] ?? esc(id)}</th><td>${fmt(achieved, 2)}%</td><td>${fmt(min, 0)}–${fmt(max, 0)}%</td><td class="${icon === '✓' ? 'status-good' : 'status-warn'}">${icon} ${delta}</td></tr>`;
  }).join('');
  const currentStatus = constraint.current_ration?.status === 'feasible' ? 'Current ration meets all macro targets' : 'Current ration is outside one or more macro targets';
  const optimizer = constraint.optimizer ?? {};
  const optimizerText = optimizer.status === 'proved_infeasible_under_active_food_set'
    ? 'The active-food feasibility check found no combination that meets all three ranges.'
    : optimizer.status === 'feasible_candidate_exists'
      ? 'A feasible combination exists within the active food set; the displayed ration has not been silently replaced.'
      : 'No macro optimizer was requested for this planning objective, so this is a ration screen rather than an infeasibility proof.';
  const adjustment = constraint.adjustment;
  const adjustmentText = adjustment ? `A nearby single-transfer adjustment is available: shift ${fmt(adjustment.share_transfer * 100, 2)} percentage points of annual food energy from ${esc(adjustment.from.replaceAll('_', ' '))} to ${esc(adjustment.to.replaceAll('_', ' '))}; estimated result ${Object.entries(adjustment.resulting_energy_percent).map(([id, value]) => `${labels[id] ?? id} ${fmt(value, 2)}%`).join(' · ')}.` : '';
  return `<div class="macro-constraint-panel" aria-live="polite"><div class="macro-constraint-heading"><h3>Macro targets and feasibility</h3><strong>${esc(currentStatus)}</strong></div><p class="small-note">The active targets are carbohydrate 45–65%, protein 10–35% and fat 20–35% of consumed food energy. These percentages use protein/carbohydrate at 0.016736 GJ/kg and fat at 0.037656 GJ/kg; fibre is reported separately and is not counted as an additional energy source.</p><div class="table-scroll"><table class="evidence-table macro-table"><thead><tr><th>Macro</th><th>Achieved</th><th>Target</th><th>Assessment</th></tr></thead><tbody>${rows}</tbody></table></div><p class="small-note"><strong>Feasibility status:</strong> ${esc(optimizerText)} ${adjustmentText}</p><details class="method"><summary>Why this status appears</summary><p>${esc(constraint.reason ?? 'The status is derived from the raw, unrounded macro shares and the active target ranges.')}</p><p class="small-note">A displayed fallback or an out-of-range current ration is not labelled as optimizer infeasible unless the active-food feasibility check explicitly reports that no feasible combination exists.</p></details></div>`;
}
function renderAgroecosystemSection() {
  const plan = agroecosystemPlanForUi();
  if (!plan) return '';
  const year = state.agroYear === 'mature' ? 'mature' : Number(state.agroYear);
  const perennial = plan.perennial_succession.years.find((row: any) => row.year === year) ?? plan.perennial_succession.years.at(-1);
  const ledger = plan.nutrient_ledger.years.find((row: any) => row.year === year) ?? plan.nutrient_ledger.years.at(-1);
  const objectiveOptions: Array<[string, string]> = [['low_external_input', 'Lowest external inputs'], ['low_land', 'Lowest productive land'], ['low_labour', 'Lowest labour'], ['nutritional_completeness', 'Nutritional completeness'], ['resilient_diverse', 'Resilience and diversity']];
  const yearOptions: Array<[string, string]> = [['1', 'Year 1'], ['2', 'Year 2'], ['3', 'Year 3'], ['5', 'Year 5'], ['8', 'Year 8'], ['10', 'Year 10'], ['15', 'Year 15'], ['30', 'Year 30'], ['mature', 'Mature']];
  const ratioOptions: Array<[string, string]> = [['0.15', '15% support plants'], ['0.25', '25% support plants'], ['0.33', '33% support plants']];
  const candidates = plan.selection.candidates.filter((row: any) => row.life_cycle !== 'support' || row.selected).slice(0, 24);
  const candidateRows = candidates.map((row: any) => `<tr><th scope="row"><label class="plant-choice"><input type="checkbox" data-agro-plant="${esc(row.plant_id)}" ${row.selected ? 'checked' : ''}><span>${esc(row.common_name)}</span></label></th><td>${row.suitability?.hard_compatible === false ? '<span class="status excluded">Excluded</span>' : row.selected ? '<span class="status selected">Selected</span>' : '<span class="status alternative">Available</span>'}</td><td>${fmt(Number(row.suitability?.suitability_score ?? 0) * 100, 0)}%</td><td>${esc(row.selection_reason ?? row.suitability?.hard_reasons?.join('; ') ?? row.suitability?.soft_reasons?.join('; ') ?? '')}</td><td>${esc(row.suitability?.evidence_status ?? 'Evidence status in contract')}</td></tr>`).join('');
  const layers = (perennial?.layers ?? []).filter((row: any) => row.retained_edible_harvest_kg > 0).map((row: any) => `${esc(row.plant_id)} ${fmt(row.retained_edible_harvest_kg, 1)} kg`).join(' · ') || 'No meaningful perennial harvest yet';
  const selectedYearDiet = plan.whole_diet.years.find((row: any) => row.year === year) ?? plan.whole_diet.years.at(-1);
  const nutritionStatus = renderMacroConstraintPanel(plan, selectedYearDiet);
  return `<section class="section tinted" id="agroecosystem"><div class="section-heading"><p class="eyebrow">Data-driven agroecosystem planner</p><h2>Plants, succession and nutrient loops</h2><p>The plant database selects compatible crops and support species from the Owen Sound / Grey County context. Outputs are scheduled by year; missing evidence stays visible instead of becoming zero production.</p></div><div class="controls-row">${selectControl('agro-objective', 'Planning objective', objectiveOptions, state.agroObjective)}${selectControl('agro-support-ratio', 'Support-plant proportion', ratioOptions, String(state.agroSupportRatio))}${selectControl('agro-year', 'Succession year', yearOptions, String(state.agroYear))}<label class="control checkbox-control"><span>Nutrient recycling</span><input id="agro-humanure" type="checkbox" ${state.agroHumanure ? 'checked' : ''}><em>treated scenario</em></label></div><p class="small-note">The support proportion is shared nominal space, not extra hectares. Human-excreta recycling is an optional treatment scenario; only recovered, treated and crop-available nutrients are credited.</p><div class="metric-grid four">${metric('Selected plants', fmt(plan.selection.selected.length, 0), 'with suitability reasons')}${metric('Annual plots', fmt(plan.annual_schedule.years.find((row: any) => row.year === (year === 'mature' ? 30 : year))?.plots?.length ?? 0, 0), 'seasonally scheduled')}${metric('Perennial harvest', `${fmt(perennial?.retained_edible_harvest_kg ?? 0, 1)} kg`, year === 'mature' ? 'mature state' : `Year ${year}`)}${metric('Nutrition constraint', nutritionStatus, `${selectedYearDiet?.macro?.energy_percent?.carbohydrate ?? '—'}% carbohydrate · ${selectedYearDiet?.macro?.energy_percent?.protein ?? '—'}% protein · ${selectedYearDiet?.macro?.energy_percent?.fat ?? '—'}% fat`)}</div><div class="agro-summary"><div><h3>Selected food and support system</h3><p>${layers}</p><p class="small-note">Perennial production changes with bearing curves, canopy/light competition and the chosen support ratio. Annual plots fill the remaining seasonal food role; harvested, stored, fed, exported and returned material are separate destinations.</p></div><div><h3>Selected-year nutrient flows</h3><p>N fixed: ${fmt(ledger?.flows?.nitrogen_fixed?.N ?? 0, 2)} kg · crop-available return: ${fmt(ledger?.flows?.nitrogen_transferred_to_crop_pool?.N ?? 0, 2)} kg</p><p>Closing stocks: N ${fmt(ledger?.balance?.closing_stock?.N ?? 0, 1)} kg · P ${fmt(ledger?.balance?.closing_stock?.P ?? 0, 1)} kg · K ${fmt(ledger?.balance?.closing_stock?.K ?? 0, 1)} kg</p><p class="small-note">A positive nutrient deficit means the selected production/export assumptions require more of that nutrient than the modeled stock currently supplies; it is not filled with an invisible amendment.</p></div></div><details class="input-details" open><summary>Inspect plant candidates and reasons</summary><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Plant</th><th>Status</th><th>Suitability</th><th>Why</th><th>Evidence</th></tr></thead><tbody>${candidateRows}</tbody></table></div></details><details class="input-details"><summary>Year-by-year production summary</summary><div class="table-scroll"><table class="evidence-table"><thead><tr><th>Year</th><th>Retained perennial harvest</th><th>Energy</th><th>Protein</th><th>Fat</th><th>Competition factor</th></tr></thead><tbody>${plan.perennial_succession.years.map((row: any) => `<tr><th scope="row">${row.year === 'mature' ? 'Mature' : row.year}</th><td>${fmt(row.retained_edible_harvest_kg, 1)} kg</td><td>${fmt(row.nutrition.energy_mj, 1)} MJ</td><td>${fmt(row.nutrition.protein_kg, 2)} kg</td><td>${fmt(row.nutrition.fat_kg, 2)} kg</td><td>${fmt(row.canopy_competition_factor * 100, 0)}%</td></tr>`).join('')}</tbody></table></div></details><p class="small-note">Evidence status is per plant and harvestable part. See <a href="#method">method and sources</a> for the database version, proxy boundaries and nutrient-ledger rules.</p></section>`;
}
function renderCapacityPageNew() { const result = householdResult(); return shell(`<section class="hero capacity-hero" id="top"><div><p class="eyebrow">Land & carrying capacity</p><h1>Land & carrying capacity</h1><p class="lede">Estimate the land required to establish and sustain a household in Owen Sound / Grey County, including food production, perennial establishment, heating biomass and resilience.</p></div><div class="hero-callout"><span>Answer-first model</span><strong>${esc(state.contract.model_version)}</strong><small>Land requirement is calculated before the detailed evidence.</small></div></section>${renderSectionNavNew()}${renderScenarioSectionNew(result)}<section class="section tinted" id="land-requirement"><div class="section-heading"><p class="eyebrow">02 · land requirement</p><h2>How much land does this household need?</h2><p>The primary answer is the peak exclusive footprint from bare land, followed by the mature requirement and the ARC policy comparison.</p></div>${renderLandRequirementNew(result)}<p><a class="button" href="${appUrl('/arc-affordability')}?${scenarioParams(true).toString()}">See what this land allocation costs</a></p></section>${renderEstablishmentSectionNew(result)}${renderFoodSectionNew(result)}${renderFoodProductionLabourSection(result)}${renderAgroecosystemSection()}${renderLivestockSectionNew(result)}${renderHeatingSectionNew(result)}${renderAnnualCropsSectionNew(result)}${renderPerennialSectionNew()}${renderMethodSectionNew()}`, 'capacity'); }

